\uline{Lemme}\quad a) $\alpha$ est injectif, et son conoyau s'identifie à
\[
\varepsilon_*(f_*(\uline{\mathcal O}_Y^*)/\uline{\mathcal O}_S^*)=q_*(\uline{\mathcal O}_Y^*)/\varepsilon_*(\uline{\mathcal O}_S^*)
\]
b) $\beta$ est bijectif

\uline{Corollaire 1}\quad $\gamma$ est surjectif, son noyau s'identifie à $\varepsilon_*(f_*\uline{\mathcal O}_Y^*)/\uline{\mathcal O}_S^*)$, d'où une suite exacte de faisceaux sur $X'$ :
\diagram{\begin{tikzcd}
0\arrow[r]&\varepsilon_*(f_*(\uline{\mathcal O}_Y^*)/\uline{\mathcal O}_S^*)\arrow[r]&\uline{\mathcal D}_{X'/S}\arrow[r]&p_*(\uline{\mathcal D}_{X/S})\arrow[r]&0
\end{tikzcd}}

\uline{Corollaire 2}\quad On a une suite exacte de faisceaux sur $S$
\diagram{\begin{tikzcd}
0\arrow[r]&f_*\uline{\mathcal O}_Y^*)/\uline{\mathcal O}_S^*\arrow[r]&f'_*(\uline{\mathcal D}_{X'/S})\arrow[r]&f_*(\uline{\mathcal D}_{X/S})\arrow[r]&0
\end{tikzcd}}

