\diagram{\begin{tikzcd}
0\arrow[r]&f_*\uline{\mathcal O}_Y^*)/\uline{\mathcal O}_S^*\arrow[r]&\unsure{\uline{\mathcal P}|\uline{P}}(X'/S)\arrow[r]&\uline{\mathcal P}(X/S)\arrow[r]&0
\end{tikzcd}}
